<script>
/* EAC V16: robust local progress persistence */
(function () {
  'use strict';
  const KEY = 'eac_course_progress_v16_' + location.pathname;

  function readState() {
    try { return JSON.parse(localStorage.getItem(KEY) || 'null'); }
    catch (e) { return null; }
  }
  function writeState(state) {
    if (!state) return;
    try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (e) {}
  }

  function getState() {
    const selectors = [
      '[data-module-index].active',
      '.module.active',
      '.module-card.active',
      '.lesson.active',
      '[aria-current="true"]'
    ];
    let moduleIndex = null;
    for (const s of selectors) {
      const el = document.querySelector(s);
      if (el) {
        moduleIndex = el.dataset.moduleIndex ?? el.dataset.module ?? el.getAttribute('data-index');
        if (moduleIndex != null) break;
      }
    }

    let slideIndex = null;
    const slideSelectors = [
      '.slide.active',
      '[data-slide].active',
      '[data-slide-index].active',
      '.lesson-slide.active'
    ];
    for (const s of slideSelectors) {
      const el = document.querySelector(s);
      if (el) {
        slideIndex = el.dataset.slideIndex ?? el.dataset.slide ?? el.getAttribute('data-index');
        if (slideIndex != null) break;
      }
    }

    /* Fall back to common global variables used by course pages. */
    const g = window;
    if (moduleIndex == null && Number.isFinite(g.currentModule)) moduleIndex = g.currentModule;
    if (slideIndex == null && Number.isFinite(g.currentSlide)) slideIndex = g.currentSlide;

    if (moduleIndex == null && slideIndex == null) return null;
    return {
      moduleIndex: moduleIndex == null ? null : Number(moduleIndex),
      slideIndex: slideIndex == null ? null : Number(slideIndex),
      savedAt: Date.now()
    };
  }

  function save() {
    const s = getState();
    if (s) writeState(s);
  }

  function restore() {
    const s = readState();
    if (!s) return;

    /* Give the course's own initialization a chance to create its UI. */
    setTimeout(function () {
      try {
        if (typeof window.goToModule === 'function' && s.moduleIndex != null) {
          window.goToModule(s.moduleIndex);
        } else if (typeof window.showModule === 'function' && s.moduleIndex != null) {
          window.showModule(s.moduleIndex);
        }
        setTimeout(function () {
          if (typeof window.goToSlide === 'function' && s.slideIndex != null) {
            window.goToSlide(s.slideIndex);
          } else if (typeof window.showSlide === 'function' && s.slideIndex != null) {
            window.showSlide(s.slideIndex);
          }
        }, 100);
      } catch (e) {}
    }, 300);
  }

  document.addEventListener('click', function (e) {
    const target = e.target.closest(
      'button, a, [role="button"], .next, .prev, .next-btn, .prev-btn, ' +
      '.module, .module-card, [data-module], [data-slide], [data-slide-index]'
    );
    if (!target) return;
    setTimeout(save, 50);
  }, true);

  window.addEventListener('load', function () {
    restore();
    setTimeout(save, 500);
  });

  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') save();
  });

  window.addEventListener('pagehide', save);
  window.addEventListener('beforeunload', save);

  /* Expose a harmless explicit save hook for the existing button/code. */
  window.eacSaveProgress = save;
})();
</script>
<?php endif; ?>
